TWComponent.script:
tw.local.sqlStatements = new tw.object.listOf.SQLStatement();

for (var i = 0; i < tw.local.transactions.listLength; i++) {

    var sqlStatement = new tw.object.SQLStatement();

    sqlStatement.sql = "SELECT AMOUNTLINKEDINBPM , ID FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE);";

    sqlStatement.parameters = new tw.object.listOf.SQLParameter();

    var param1 = new tw.object.SQLParameter();
    param1.value = tw.local.transactions[i].referenceNumber;
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, param1);

   var param2 = new tw.object.SQLParameter();
    param2.value = tw.local.transactions[i].postingDate;
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, param2);

    tw.local.sqlStatements.insertIntoList(tw.local.sqlStatements.listLength, sqlStatement);

}

log.info("Final tw.local.sqlStatements: " + tw.local.sqlStatements);

tw.local.transactionsIDs = [];

if (tw.local.sqlResults.listLength > 0) {
    for (var i = 0; i < tw.local.sqlResults.listLength; i++) {
        var result = tw.local.sqlResults[i];

        if (!!result.rows.listLength > 0 && result.rows[0].data) {
            tw.local.transactions[i].existAmount = result.rows[0].data[0];
            tw.local.transactionsIDs.insertIntoList(tw.local.transactionsIDs.listLength, result.rows[0].data[1]);
        }
    }
}

